"""Explicit CTB authoring: licensing and first administrative infractions."""
import copy,json,sys
from pathlib import Path
p=Path(sys.argv[1]);old=json.loads((p/'batch-04-existing.json').read_text());expected={r['unit']['unit_key']:r for r in old};rows={}
CTB='https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm'
L2020='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14071.htm'
L2022='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14440.htm'
L2023='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14599.htm'
L14921='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14921.htm'
L15153='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15153.htm'
L15503='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15503.htm'
R1020='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao10202025.pdf'
R1031='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/resolucao10312026.pdf'
R923='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-Senatran/resolucoes2/Resoluo923compilado.pdf'
R819='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao8192021.pdf'
STFRECUSA='https://noticias.stf.jus.br/postsnoticias/bafometro-multa-a-motorista-que-recusa-teste-e-valida-decide-stf/'
STF2998='https://noticias.stf.jus.br/postsnoticias/supremo-julga-inconstitucional-norma-do-ctb-que-permite-ao-contran-criar-sancoes-para-infracoes-de-transito/'
def add(n,case,variation,q1,q2,term,meaning,**patch):
 key='art-'+str(n);e=copy.deepcopy(expected[key]['explanation']);data={k:e[k] for k in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 data.update(exemplo=case+' Variação: '+variation,prova=[q1,q2],termos=[dict(termo=term,significado=meaning)])
 data['pontos']+=patch.pop('extra_points',[]);data['atencao']+=patch.pop('notes',[]);data['remissoes']=list(dict.fromkeys([CTB,*data['remissoes'],*patch.pop('sources',[])]));data.update(patch);rows[key]=data
add(140,'Um adolescente emancipado requer habilitação. Resposta: emancipação civil não substitui o requisito de imputabilidade penal do inciso I.', 'Um candidato satisfaz os requisitos iniciais: isso não equivale a aprovação automática nos exames ou autorização imediata para dirigir.', 'Ser civilmente emancipado dispensa a imputabilidade penal? Não. O art. 140 exige imputabilidade penal, além de saber ler/escrever e documento de identidade ou equivalente.', 'As informações do candidato são cadastradas no Renavam? Não. O parágrafo prevê Renach; Renavam é cadastro de veículos, distinto do de habilitação.', 'Imputabilidade penal','Requisito próprio, distinto de capacidade civil adquirida por emancipação.',notes=['Não afirmar que só ser adulto assegura habilitação: requisitos e exames continuam.'],sources=[L2023])
add(141,'Um município disciplina a autorização de condução de veículo de tração animal. Resposta: o §1º reserva essa matéria aos municípios.', 'Autorizar ciclomotor integra regulamentação do Contran, não se confunde com tração animal por baixa velocidade.', 'O processo de habilitação é normatizado livremente por cada instrutor? Não. A regulamentação cabe ao Contran, com execução pelos órgãos competentes.', 'A Resolução 789/2020 permanece regulamento atual único de formação? Não. A Resolução 1020/2025 a revogou e reorganizou os procedimentos.', 'ACC','Autorização para Conduzir Ciclomotor, distinta de autorização municipal de tração animal.',notes=['Resolução 1020/2025 vigente desde publicação de 9/12/2025; preservar transições e não recuperar obrigatoriedade universal de autoescola.'],sources=[R1020])
add(142,'Uma turista apresenta habilitação estrangeira. Resposta: o reconhecimento depende do regime internacional e das normas do Contran, não apenas da existência do documento.', 'A validade no país emissor não resolve automaticamente prazo, documentos e categoria admitidos no Brasil.', 'Qualquer habilitação estrangeira é automaticamente reconhecida por tempo ilimitado? Não. O artigo subordina o reconhecimento às condições internacionais e à regulamentação do Contran.', 'O artigo fixa sozinho prazo universal de seis meses para toda pessoa? Não. Remete ao regime aplicável; hipóteses regulamentares e condições do país devem ser examinadas.', 'Reconhecimento condicionado','Aceitação da habilitação conforme convenções e requisitos regulamentares.',notes=['Resolução 1020/2025, arts. 101 seguintes, disciplina estrangeiros. Não ensinar prazo indiscriminado sem verificar requisitos e situação.'],sources=[R1020])
add(143,'Um veículo híbrido com tração predominantemente elétrica tem PBT de 4.000 kg. Resposta: pode entrar no §2º-A da categoria B, respeitados eventuais critérios adicionais do Contran.', 'Um híbrido sem tração predominantemente elétrica não ganha automaticamente o teto de 4.250 kg só por ser chamado híbrido.', 'O teto de 4.250 kg da B vale para qualquer automóvel a combustão? Não. A Lei 15.503/2026 delimita propulsão elétrica ou híbrida com tração predominantemente elétrica e regulamento adicional.', 'Duas unidades tracionadas pequenas dispensam E porque cada uma pesa menos de 6.000 kg? Não. O §3º aplica o inciso V a combinação com mais de uma unidade tracionada independentemente de peso/capacidade.', 'Categoria e combinação','Enquadramento que considera tratora, unidades acopladas e exceções específicas.',simples='A: motorizado de duas/três rodas. B: fora da A, PBT até 3.500 kg e até oito lugares excluído motorista, com exceções. C abrange B e carga acima de 3.500 kg; D abrange B/C e passageiros acima de oito lugares. E considera unidade acoplada de 6.000 kg ou mais ou lotação acima de oito, e combinações com mais de uma unidade tracionada. §2º: motor-casa tem redação específica com OU. §2º-A de 2026: elétrica ou híbrida com tração predominantemente elétrica, PBT até 4.250 kg, observado regulamento. C exige um ano de B e não mais de uma gravíssima em doze meses.',pontos=['B ordinária: até 3.500 kg E até oito lugares, excluído motorista.','Lei 15.503/2026 publicada/vigente em 14/9/2026: §2º-A, elétrica ou híbrida com tração predominantemente elétrica até 4.250 kg.','C: um ano de B; não mais de UMA gravíssima nos últimos doze meses.','E: unidade acoplada com 6.000 kg OU MAIS ou mais de oito lugares; §3º: mais de uma unidade tracionada.','§4º: B/C/D podem conduzir combinação no recorte próprio de tratora, acoplada MENOR que 6.000 kg E até oito lugares, respeitada CMT.','Motor-casa: preservar OU da redação do §2º; não substituir silenciosamente por E nem generalizar esse recorte aos outros tipos.'],atencao=['Atualização normativa de 14/9/2026 não é a data original do CTB nem a data da conferência de 13/10/2026.','Não recuperar restrição de graves/reincidência média para acesso à C; não tratar qualquer híbrido como exceção.'],sources=[L15503,L2022])
add(144,'Um trator de rodas executa trabalho agrícola e é conduzido na via por habilitado em B. Resposta: o parágrafo admite a hipótese, sem exigir indistintamente C/D/E.', 'A exceção não libera toda máquina de construção para qualquer habilitado em B; analisar o tipo/destinação previstos.', 'O caput não admite nenhuma exceção à exigência C/D/E? Não. O parágrafo inclui trator de roda e equipamentos destinados a trabalho agrícola também para B.', 'Habilitação B permite qualquer máquina de terraplenagem por analogia? Não. A exceção é delimitada, não autorização geral para toda máquina automotora.', 'Exceção agrícola','Extensão da B no recorte do parágrafo, sem equiparação universal de maquinário.',notes=['Não extrapolar a exceção para qualquer trator/máquina apenas pelo nome popular.'])
add(145,'O candidato tem B há dois anos e pretende D. Resposta: satisfaz uma alternativa temporal, mas precisa dos demais requisitos do artigo.', 'Ter C há um ano permite outra alternativa para D e o requisito temporal de E; participar do curso não depende do histórico do inciso III, conforme parágrafo.', 'Para D são cumulativos dois anos de B e um ano de C? Não. O inciso II, a, apresenta alternativas com OU, mantendo os demais requisitos.', 'Duas gravíssimas impedem até mesmo participar do curso especializado pelo artigo? Não. O parágrafo separa participação no curso do requisito do inciso III; não equivale a aprovação final na habilitação.', 'Requisito prévio','Condição para a categoria/atividade, distinta da possibilidade de participar do curso.',notes=['Histórico atual: não mais de uma gravíssima em doze meses. Texto da idade: maior de vinte e um anos; não substituir silenciosamente sua expressão.','Formação especializada deve integrar Resolução 1020/2025, não programa antigo revogado como única fonte.'],sources=[L2020,R1020])
add('145-a','Uma motorista de ambulância comprova formação e reciclagem específica no período de cinco anos. Resposta: é exigência adicional ao regime do art. 145.', 'Ser habilitada em D não substitui o treinamento especializado e a reciclagem própria.', 'O intervalo legal da reciclagem da ambulância é de dois anos? Não. O art. 145-A prevê cinco anos, integrado à normatização do Contran.', 'A exigência substitui integralmente todos os requisitos do art. 145? Não. O texto diz além do disposto no art. 145, indicando exigência adicional.', 'Reciclagem de ambulância','Formação periódica específica em cinco anos, distinta de toda renovação de CNH.',notes=['Resolução 1020/2025, art. 75: validade de cinco anos a partir da aprovação; atualização registrada no Renach tem regime próprio.'],sources=[R1020])
add(146,'Condutor de B pretende conduzir veículo da C. Resposta: deve realizar exames complementares exigidos para a categoria pretendida, sem dispensar demais requisitos.', 'Conduzir um tipo que já está incluído na categoria atual não é automaticamente mudança de categoria; conferir art. 143.', 'O artigo dispensa todo exame para ampliar categoria? Não. Exige exames complementares próprios da habilitação pretendida.', 'Ter qualquer habilitação libera condução de categoria superior? Não. A ampliação depende dos requisitos e exames pertinentes; não decorre de possuir CNH em geral.', 'Exame complementar','Avaliação própria da categoria pretendida, distinta de livre extensão da licença.',notes=['Não confundir inclusão legal de veículos na categoria existente e processo de mudança/adicionamento.'],sources=[R1020])
add('147-a','Candidata com deficiência auditiva requer na inscrição intérprete de Libras para aulas. Resposta: a garantia abrange aulas práticas e teóricas e acessibilidade em todas as etapas.', 'Material audiovisual só com legenda não satisfaz automaticamente a associação de legenda oculta e tradução simultânea em Libras prevista no §1º.', 'A acessibilidade se limita à prova teórica? Não. O caput a assegura em todas as etapas, e o §2º inclui acompanhamento das aulas práticas e teóricas.', 'O direito autoriza presumir que toda pessoa surda usa a mesma comunicação? Não. A acessibilidade deve respeitar a comunicação efetiva; o artigo garante os recursos e o requerimento descritos.', 'Acessibilidade comunicacional','Condições para participação efetiva, sem presumir incapacidade ou método único.',notes=['Incluído pela LBI, Lei 13.146/2015; não converter deficiência auditiva em incapacidade automática para habilitação.'])
add('148-a','Uma questão afirma que toxicológico jamais alcança categoria A ou B. Resposta: erra diante do §10 incluído na Lei 15.153/2025 após promulgação de partes vetadas, que prevê primeira habilitação A/B.', 'Isso não estende automaticamente o exame periódico de dois anos e seis meses do §2º a todo habilitado A/B; o periodicismo continua no recorte C/D/E menores de setenta.', 'É correto manter exercício dizendo que categoria B nunca precisa de toxicológico? Não. O §10 atual inclui primeira habilitação A/B; distinguir previsão legal e regras operacionais pertinentes.', 'Um resultado negativo elimina toda fiscalização de influência atual de substância? Não. O exame de larga janela tem objeto diferente da abordagem e prova de influência/alteração na condução.', 'Larga janela de detecção','Avaliação retrospectiva mínima de noventa dias, distinta da fiscalização instantânea.',simples='C/D/E: negativo para obtenção/renovação; abaixo de setenta anos, exame periódico a cada dois anos e seis meses, independente dos demais exames. Janela mínima de noventa dias; contraprova e recurso sem efeito suspensivo. Positivo no periódico: suspensão de três meses, levantamento condicionado a novo negativo no Renach. ATUALIZAÇÃO: §10 da Lei 15.153/2025 também prevê negativo na PRIMEIRA habilitação A/B, sem criar periodicismo universal dessas categorias. Aplicação operacional e calendários regulamentares devem ser conferidos; não ensinar exclusão absoluta de A/B.',pontos=['C/D/E: obtenção/renovação e periódico, abaixo de setenta, a cada 2 anos e 6 meses.','§10: primeira habilitação A/B, incluída após promulgação de partes vetadas da Lei 15.153/2025.','Janela mínima: 90 dias; recurso/contraprova SEM efeito suspensivo.','§5º: positivo no PERIÓDICO, suspensão de três meses e negativo no Renach para levantamento; vedadas outras penalidades nesse recorte.','§9º: comunicação de vencimento com trinta dias de antecedência via sistema eletrônico.','§7º: laboratórios credenciados, livre concorrência; vedados preço público fixado, limite de número/locais e exclusividade territorial.','§11: posto de coleta em ambiente próprio e segregado na clínica, contratado por laboratório credenciado; não habilita a clínica automaticamente como laboratório.'],atencao=['Não repetir exercício antigo só C/D/E: o §10 alcança primeira A/B. Não estender seu alcance à renovação/periódico universal de A/B.','Regulamento 923 compilado consultado no recorte C/D/E. Não certificada integralmente a implantação/calendário operacional da expansão A/B.','Distinguir não realização, positivo no exame do caput e positivo no periódico; arts. 165-B/C/D não são hipóteses idênticas.'],sources=[L15153,R923,L2023])
add(150,'Uma empresa contrata condutores para operar a frota. Resposta: tem dever de fornecer os cursos mencionados e outros conforme normas do Contran.', 'O artigo não autoriza repetir todo curso em qualquer renovação sem considerar se já foi realizado e o regime atual.', 'O caput manda repetir cursos indiscriminadamente mesmo quando o condutor já os possui? Não. Delimita condutor que não tenha direção defensiva e primeiros socorros, conforme normatização.', 'A obrigação de fornecer cursos é exclusiva do próprio motorista contratado? Não. O parágrafo atribui o fornecimento à empresa que utiliza condutores contratados em sua frota.', 'Formação continuada','Capacitação conforme situação e normatização, não repetição automática de todo curso.',notes=['A remissão ao artigo anterior deve ser integrada ao regime atual de exames; o art. 149 está revogado. Não recuperar procedimento antigo apenas por remissão residual.'],sources=[R1020])
add(152,'A comissão tem três membros, um habilitado na categoria igual ou superior à pretendida. Resposta: corresponde à composição legal; não exige todos com essa categoria.', 'Na regulamentação 1020, um preposto acompanha o candidato e a comissão avalia; não exigir os três sentados no veículo em toda prova.', 'Todos os membros da comissão precisam de categoria igual ou superior? Não. O §1º exige pelo menos um; o número total da comissão é três.', 'Curso corporativo dispensa qualquer exame, mesmo sem aprovação no curso? Não. O §2º limita a dispensa aos exames com aprovação observadas normas do Contran e documentação do §3º.', 'Comissão examinadora','Colegiado de avaliação, distinto de exigir presença simultânea de todos no veículo.',notes=['Resolução 1020/2025, art. 43: acompanhamento por preposto, comissão de três e possibilidade regulamentada de avaliação remota; não dispensar requisitos legais.'],sources=[R1020])
add(153,'O prontuário identifica instrutores e examinadores da formação. Resposta: permite vincular agentes ao processo, sujeitos às sanções segundo a falta e o regulamento.', 'A identificação não gera cancelamento automático por qualquer erro do aluno; analisar conduta e procedimento sancionador.', 'O rol textual do parágrafo contém apenas multa ao examinador? Não. Prevê advertência, suspensão e cancelamento da autorização para atividade, conforme falta.', 'Todo erro do candidato impõe automaticamente punição ao instrutor? Não. Responsabilidade exige examinar conduta, falta e regime aplicável, sem automatismo pelo resultado do aluno.', 'Autorização profissional','Vínculo para exercer instrução/exame, distinto da CNH pessoal do profissional.',notes=['Não confundir cancelamento de autorização profissional e cassação da CNH do art. 263.'],sources=[R1020])
add(154,'Veículo da categoria de aprendizagem destinado à formação tem faixa amarela de vinte centímetros. Resposta: aplicar esse regime e idade máxima por categoria, sem contar ano de fabricação.', 'Veículo usado eventualmente na aprendizagem tem faixa branca removível; Resolução 1020, art. 128, distingue-o do destinado à formação.', 'Faixa da autoescola tem quarenta centímetros como a escolar? Não. O art. 154 usa vinte; quarenta é o recorte de identificação escolar do art. 136.', 'Idade máxima do veículo de formação se conta pelo início do uso na autoescola? Não. O §2º manda não computar ano de fabricação e fixa 8/12/20 por categoria; não contar por tempo comercial de uso.', 'Formação e uso eventual','Regimes de identificação distintos, também distinguidos na Resolução 1020.',atencao=['Lei 14.921/2024 publicada/vigente em 11/7/2024: máximo A=8, B=12, C/D/E=20, NÃO computado ano de fabricação.','Resolução 1020/2025, art. 128: destinados à formação são categoria aprendizagem; eventual tem identificação branca removível. Não afirmar exigência idêntica para qualquer carro particular usado em aula.'],sources=[L14921,R1020])
add(155,'Um instrutor autorizado não pertence a autoescola, mas orienta aprendizagem regular. Resposta: a redação atual admite pertencente ou não à entidade credenciada.', 'Ser condutor experiente não equivale a instrutor autorizado nem substitui autorização de aprendizagem.', 'Instrutor precisa sempre ser empregado de autoescola? Não. O caput atual admite instrutor autorizado pertencente ou não a entidade credenciada.', 'A flexibilização elimina autorização do instrutor e condições da aprendizagem? Não. Autorização estadual/distrital e regime regulamentar permanecem exigíveis.', 'Instrutor autorizado','Profissional autorizado pelo órgão competente, com ou sem vínculo a entidade.',notes=['Lei 14.599/2023 e Resolução 1020/2025: distinguir flexibilização de vínculo e ausência de controle.'],sources=[L2023,R1020])
add(156,'Uma entidade pretende oferecer formação de condutores. Resposta: o credenciamento e as exigências de instrutores/examinadores obedecem à regulamentação do Contran.', 'A função normativa nacional não significa que todo ato de credenciamento individual seja praticado diretamente pelo Contran.', 'Só autoescola aparece como entidade de formação no artigo? Não. O caput também menciona outras entidades destinadas à formação, conforme regulamentação.', 'Definir normas e executar credenciamento são sempre a mesma competência? Não. O artigo atribui regulamentação ao Contran; atos executivos têm disciplina e órgãos próprios.', 'Credenciamento','Vínculo regulado de prestação do serviço, distinto da elaboração nacional de normas.',notes=['Resolução 1020/2025 é fonte atual; não recuperar 789/2020 como vigente.'],sources=[R1020])
add(158,'Na aula estão aprendiz, instrutor autorizado e um acompanhante. Resposta: o §1º permite só mais um acompanhante além dos dois.', 'Instrutor não autorizado ou aula fora das condições do órgão viola os requisitos, mesmo sem acompanhante adicional.', 'O limite é um ocupante total no veículo de aprendizagem? Não. Permite aprendiz e instrutor, além de apenas mais um acompanhante.', 'O §2º revogado ainda impõe a mesma restrição histórica vigente? Não. Deve ser tratado como marca de revogação, sem gerar exercício de dever antigo.', 'Aprendizagem acompanhada','Instrução regular com profissional autorizado e limite adicional de acompanhante.',notes=['Integrar Resolução 1020/2025; autorização não equivale a livre aprendizagem desacompanhada.'],sources=[R1020])
add(160,'Condutor condenado por delito de trânsito pretende voltar a dirigir. Resposta: o caput exige novos exames na forma do Contran, inclusive na hipótese de prescrição que especifica.', 'Condutor apenas envolvido em sinistro grave não recebe automaticamente a mesma consequência: o §1º diz poderá e assegura ampla defesa.', 'Todo envolvimento em sinistro grave exige automaticamente novos exames? Não. O §1º remete ao juízo da autoridade estadual e assegura ampla defesa, sem condenação presumida.', 'Apreender documento do §2º restaura a antiga penalidade de apreensão do veículo? Não. São objeto e regime diferentes; não confundir documento e veículo nem medida e pena.', 'Retorno à condução','Exames conforme hipótese legal e procedimento, distinto de culpa automática no sinistro.',notes=['Distinguir condenado do caput e envolvido do §1º; não presumir culpa pelo mero envolvimento.'])
add(161,'Uma resolução define requisito técnico e uma autoridade pretende inventar por ela sanção inédita. Resposta: regulamentação não equivale à criação livre de sanções; a ADI 2998 afastou essa autorização.', 'Conduta pode gerar infração administrativa e crime quando preencher tipos próprios, não porque toda irregularidade administrativa é crime.', 'Toda infração administrativa constitui automaticamente crime de trânsito? Não. O capítulo penal tem requisitos próprios, distintos do simples descumprimento administrativo.', 'Contran pode criar qualquer sanção como legislador pelo parágrafo antigo? Não. A ADI 2998 afastou essa autorização; o parágrafo atual foi revogado pela Lei 14.071/2020.', 'Reserva legal sancionatória','Regulamentação técnica não concede poder ilimitado de criar punições.',notes=['Redação atual usa código e legislação complementar. Não recuperar o parágrafo revogado ou a expressão afastada judicialmente como poder sancionatório livre.'],sources=[STF2998,L2020])
add(162,'Uma pessoa com B dirige motocicleta que exige A. Resposta: categoria diferente tem multa duas vezes, distinta da multa três vezes de não possuir habilitação.', 'A CNH venceu há exatamente trinta dias: o inciso V exige MAIS DE trinta dias; analisar também hipóteses atuais de validade e exceções, sem alterar o limiar.', 'Sem habilitação e categoria diferente têm multiplicador idêntico? Não. Incisos I/II usam três vezes; o III, duas vezes, com medidas próprias.', 'A infração administrativa por não possuir habilitação prova automaticamente crime do art. 309? Não. O tipo penal exige seus próprios elementos, inclusive perigo de dano; não deduzir crime de toda autuação.', 'Categoria diferente','Possuir habilitação incompatível com o veículo, distinto de não possuir licença.',atencao=['Inciso V: vencida há MAIS DE trinta dias. Lei 14.440/2022 retirou recolhimento do documento desse inciso, mas não foi a primeira lei a tornar a hipótese gravíssima.','Cursos obrigatórios do inciso VII precisam do regime atual, incluindo Resolução 1020/2025; não recuperar curso revogado como único requisito.','Deficiência por si não constitui infração: inciso VI trata de deixar de usar auxílio/adaptação imposto ao habilitar/renovar.'],sources=[L2022,R1020])
add(163,'O responsável entrega diretamente a direção a pessoa sem habilitação. Resposta: incidem as infrações e penalidades correspondentes do art. 162, com medida referida ao inciso III.', 'Não presumir que toda entrega configura crime do art. 310 sem analisar elementos e hipótese própria, ainda que esfera administrativa possa coexistir.', 'A medida administrativa reproduz indistintamente qualquer medida do art. 162? Não. O art. 163 remete especificamente à medida do inciso III, distinguindo-a das penalidades.', 'O multiplicador é sempre três vezes em qualquer entrega irregular? Não. Depende da condição do art. 162 aplicável, como categoria diferente com duas vezes.', 'Entrega da direção','Conduta de disponibilizar diretamente a condução a pessoa em condição vedada.',notes=['Distinguir entregar (163), permitir posse e condução (164) e confiar a pessoa sem condição segura (166).'])
add(164,'O responsável permite que pessoa sem habilitação tome posse do veículo e passe a conduzi-lo na via. Resposta: estão presentes os elementos administrativos descritos no artigo.', 'Permitir apenas acesso ao carro, sem condução na via, não deve ser equiparado automaticamente à descrição completa do art. 164.', 'A mera presença de pessoa sem habilitação dentro do carro completa todo art. 164? Não. O texto inclui permitir posse e que passe a conduzi-lo na via.', 'A medida remete a qualquer inciso do art. 162 livremente? Não. Remete à medida do inciso III; infração e penalidade dependem da condição correspondente.', 'Permissão de condução','Tolerar posse e condução na via na condição legal vedada, não simples proximidade.',notes=['Não presumir permissão por vínculo familiar sem comprovar a conduta; integrar a hipótese concreta.'])
add(165,'A fiscalização usa só pré-teste passivo indicativo de álcool. Resposta: a Resolução 1031/2026 não permite fundamentar autuação apenas nesse pré-teste; exige procedimento válido de constatação.', 'O CTB conserva recolhimento da habilitação no texto, mas a Resolução 1031, art. 12, orienta que o agente não recolha o documento nessa abordagem; suspensão segue procedimento próprio.', 'O pré-teste passivo sozinho comprova a infração para autuar? Não. O art. 4º, §2º, da Resolução 1031 atribui caráter indicativo e exige procedimento de constatação conforme seus requisitos.', 'A suspensão legal de doze meses corresponde a apreensão automática da CNH física no local? Não. Distinguir texto legal de medidas e procedimento atual da Resolução 1031, art. 12; suspensão tem processo próprio.', 'Pré-teste indicativo','Triagem que não substitui prova válida para autuação por influência de álcool.',simples='Dirigir sob influência de álcool/outra substância descrita é gravíssima: multa dez vezes e suspensão por doze meses; multa em dobro na reincidência em até doze meses. Distinguir infração, crime e procedimentos de prova. Resolução 1031/2026, publicada em 18/8, revogou 432/2013: pré-teste é só indicativo, constatação tem requisitos e erro metrológico, e art. 12 prevê não recolhimento do documento pelo agente na abordagem, embora o texto do CTB conserve essa medida. A suspensão segue procedimento próprio.',pontos=['Multa DEZ vezes; suspensão DOZE meses; reincidência em até doze meses dobra a MULTA.','Resolução 1031/2026: pré-teste não fundamenta sozinho autuação; distinguir medição realizada e valor considerado.','Sinais: pelo menos DOIS em conjunto, descritos no auto/termo; não um sinal isolado universal.','Retenção/liberação do veículo seguem requisitos de condutor seguro; não antiga penalidade de apreensão.','Art. 12 regulamentar: agente não recolhe documento nessa abordagem; suspensão não é apreensão física automática.'],atencao=['Texto legal e procedimento regulamentar devem ser diferenciados, sem alterar a transcrição oficial do CTB.','Art. 16 da Resolução 1031: alterações no anexo do Manual 985 têm vacância de sessenta dias da publicação, até 17/10/2026; em 13/10 não aplicar como vigentes essas fichas futuras. Os demais artigos vigoram desde 18/8/2026.','Não presumir crime de todo resultado administrativo; o art. 306 exige seus próprios elementos.'],sources=[R1031])
add('165-a','Condutor recusa procedimento adequado regularmente ofertado e não apresenta dois sinais de alteração. Resposta: a Resolução 1031 enquadra a recusa no art. 165-A, com multa dez vezes e suspensão de doze meses.', 'Se há pelo menos dois sinais de alteração, a resolução distingue aplicação do art. 165; não autuar cumulativamente por automatismo pelos mesmos fatos.', 'O STF considerou toda sanção administrativa por recusa inconstitucional? Não. O Tema 1079, RE 1224374, validou a previsão administrativa sem equiparar recusa isolada a crime.', 'A recusa sozinha comprova automaticamente crime do art. 306? Não. A infração de recusa é autônoma administrativa; crime exige elementos e provas próprios.', 'Recusa administrativa','Hipótese autônoma validada pelo STF, distinta de presumir crime de embriaguez.',atencao=['Tema 1079/STF, julgamento de 19/5/2022: validade das sanções administrativas; não usar linguagem imprecisa de apreensão da CNH por um ano para confundir suspensão e documento.','Resolução 1031/2026, art. 8º, §§1º/2º: sem dois sinais, recusa; com ao menos dois sinais, art. 165.','Art. 12 da resolução: agente não recolhe documento nessa abordagem; art. 16 difere a vigência das fichas do Manual para 17/10/2026, sem diferir todo o ato.'],sources=[STFRECUSA,R1031])
add('165-b','Condutor de C sujeito ao exame periódico dirige 31 dias após o vencimento sem realizá-lo. Resposta: verificar o parágrafo, que exige condução após o trigésimo dia, com multa cinco vezes.', 'A ausência de condução não completa essa descrição, mas pode integrar 165-D no recorte periódico; não confundir ambos.', 'O art. 165-B periódico exige conduzir o veículo? Sim. O caput e o parágrafo descrevem dirigir sem exame, após o trigésimo dia do vencimento no periódico.', 'A primeira ocorrência tem suspensão expressamente cumulada em todo caso pelo caput? Não. A redação prevê cinco vezes e, na reincidência até doze meses, dez vezes e suspensão; integrar outras hipóteses sem somar por automatismo.', 'Condução sem exame','Hipótese de dirigir sem requisito toxicológico, distinta de mero atraso do periódico.',notes=['Lei 14.599/2023: produção de efeitos das alterações toxicológicas desde 1º/7/2023 e implementação escalonada; não usar prazo transitório vencido como regra permanente.','Separar exames do caput/§2º e alcance do §10 atual para primeira A/B; não aplicar periódico indiscriminadamente a A/B.'],sources=[L2023,R923])
add('165-c','Condutor dirige tendo resultado positivo no exame do CAPUT do art. 148-A. Resposta: é a hipótese do art. 165-C, multa cinco vezes e agravamento por reincidência.', 'Positivo no exame periódico do §2º tem também disciplina do §5º do art. 148-A; não substituir as hipóteses por uma regra única sem distinção.', 'O art. 165-C pune só ter resultado positivo sem jamais dirigir? Não. O texto descreve DIRIGIR tendo o resultado positivo no exame do caput.', 'A primeira ocorrência tem multa dez vezes pelo art. 165-C? Não. O caput prevê cinco vezes; dez vezes e suspensão estão no regime da reincidência em até doze meses.', 'Positivo e condução','Combinação dos elementos do art. 165-C, não sinônimo de toda irregularidade toxicológica.',notes=['Não confundir exame do caput, periódico e influência atual na fiscalização do art. 165.'],sources=[L2023])
add('165-d','Condutor de D sujeito ao periódico deixa passar mais de trinta dias do prazo sem fazer exame. Resposta: o artigo descreve deixar de realizar; não exige flagrante dirigindo como o 165-B.', 'A aplicação cabe ao órgão de registro da CNH, não automaticamente ao órgão onde o veículo foi registrado ou onde se encontrou o condutor.', 'O art. 165-D exige necessariamente condução na abordagem? Não. Descreve não realizar exame periódico após trinta dias do vencimento, distinguindo-se do 165-B.', 'A penalidade deste artigo inclui suspensão de três meses expressa no próprio caput? Não. Prevê multa cinco vezes; suspensão do art. 148-A, §5º, tem outra hipótese e precisa ser integrada corretamente.', 'Mero atraso periódico','Não realização além do marco, distinta de dirigir sem exame ou com positivo.',notes=['Aplicação específica pelo órgão de registro da CNH; não confundir CNH e registro do veículo.','Lei 14.599/2023: distinguir efeitos desde 1º/7/2023 e calendários transitórios de regularização, sem ensinar prorrogação histórica como dispensa atual.'],sources=[L2023,R923])
add(166,'O responsável confia a direção a habilitado que está fisicamente sem condição segura para dirigir. Resposta: a habilitação não elimina a hipótese gravíssima do artigo.', 'Deficiência não significa por si falta de condição: examinar condição efetiva e adaptações, sem presumir incapacidade.', 'Só entregar a não habilitado configura o art. 166? Não. O texto inclui pessoa mesmo habilitada que, por estado físico ou psíquico, não pode dirigir com segurança.', 'A infração autoriza discriminar qualquer condutor com deficiência? Não. Exige condição concreta de insegurança, sem equiparar deficiência e incapacidade automaticamente.', 'Condição segura','Aptidão concreta para dirigir no momento, distinta da simples posse de CNH.',notes=['Distinguir arts. 163/164, condição de habilitação, e art. 166, condição física/psíquica de segurança.'])
add(167,'Passageiro traseiro deixa de usar cinto em trajeto curto. Resposta: no regime aplicável, infração grave com multa e retenção até colocar o cinto.', 'Uma hipótese regulamentar válida do art. 65 deve ser examinada; não criar dispensa pessoal por conveniência ou duração do trajeto.', 'A falta do cinto é infração gravíssima por envolver segurança? Não. O art. 167 a classifica como GRAVE, sem confundir importância do cuidado e classe legal.', 'O artigo permite liberação sem sanar a falta do cinto em sua medida textual? Não. A medida é retenção até a colocação pelo infrator, integrada às condições aplicáveis.', 'Retenção para saneamento','Medida de regularização, distinta da remoção ou de antiga apreensão penalizadora.',notes=['Condutor e passageiro abrangidos; integrar exceções regulamentadas do art. 65 sem inventar trajeto curto.'])
add(168,'Uma criança de seis anos em carro particular vai sem o dispositivo adequado às suas condições na Resolução 819. Resposta: analisar o transporte irregular, infração gravíssima, com retenção até sanar.', 'Não exigir cadeirinha universal para toda criança de oito anos: idade, peso, altura e condições do veículo definem o equipamento e as exceções.', 'Transportar criança irregularmente tem a mesma classe grave da falta comum de cinto? Não. O art. 168 é gravíssima, distinto da classe do art. 167.', 'Toda criança menor de dez deve usar o mesmo dispositivo? Não. Integrar art. 64 e Resolução 819, com critérios de retenção e exceções delimitadas.', 'Retenção infantil','Proteção adequada à criança, diferente de aplicar um único equipamento a todas.',atencao=['Não recuperar exemplo antigo de cadeirinha como equipamento universal para idade de seis anos; conferir assento de elevação e demais critérios do anexo.','Retenção até saneamento, não penalidade antiga de apreensão do veículo.'],sources=[R819])
add(169,'Condutor está desatento e não há descrição mais específica demonstrada. Resposta: o art. 169 tem classe leve e multa, observada a hipótese concreta.', 'Segurar/manusear celular tem tipo específico no art. 252; não reduzir automaticamente toda distração a infração leve.', 'Dirigir sem atenção é classificado como grave pelo art. 169? Não. O texto o classifica como LEVE, com multa.', 'Toda conduta perigosa ou distração sempre se enquadra somente no 169? Não. Conferir tipos específicos e seus elementos, como uso de celular, sem generalização.', 'Tipo residual','Descrição geral de falta de atenção, quando a conduta não exige enquadramento específico.',notes=['Evitar tornar o artigo forma de rebaixar qualquer infração mais específica.'])
add(170,'Motorista dirige para ameaçar pedestres que atravessam. Resposta: gravíssima, com multa e suspensão, além das medidas textuais pertinentes.', 'Uma manobra inadvertida não deve ser equiparada automaticamente à descrição de ameaça sem examinar os elementos concretos.', 'O art. 170 prevê apenas multa sem suspensão? Não. A penalidade inclui multa E suspensão do direito de dirigir.', 'A infração exige ameaça somente contra outro veículo? Não. Inclui pedestres atravessando a via pública e demais veículos.', 'Ameaça na direção','Uso da condução para ameaçar no recorte descrito, distinto de qualquer erro de manobra.',notes=['Não presumir crime ou ameaça por todo erro; esfera penal depende de requisitos próprios.'])
add(171,'Condutor usa o veículo para lançar água de uma poça sobre pedestre. Resposta: a descrição é média com multa, quando comprovada a conduta do artigo.', 'Derramamento de carga ou jogar objeto do veículo tem descrições próprias; não tratar todo episódio de material na via como idêntico.', 'A conduta descrita no art. 171 é leve? Não. Usar o veículo para arremessar água ou detritos sobre pedestres/veículos é MÉDIA.', 'O artigo alcança apenas água lançada contra pedestre? Não. Inclui água ou detritos sobre pedestres ou veículos, no recorte de uso do veículo para arremessar.', 'Arremesso pelo veículo','Conduta do art. 171, distinta de atirar objeto manualmente ou perder carga.',notes=['Distinguir art. 171 e art. 172; não dispensar prova da conduta pela mera existência de poça.'])
add(172,'O passageiro atira objeto do veículo ou alguém o abandona na via. Resposta: a descrição administrativa é média com multa, examinada a atribuição da responsabilidade.', 'Não confundir arremesso de água pelo próprio veículo do art. 171 com toda hipótese de lixo ou substância abandonada.', 'O art. 172 só descreve atirar objeto enquanto o veículo está em alta velocidade? Não. Inclui atirar do veículo OU abandonar na via, sem esse requisito inventado.', 'A classe da infração é gravíssima para qualquer objeto por risco potencial? Não. O tipo do art. 172 é MÉDIA; outros crimes/infrações exigem requisitos específicos.', 'Abandono na via','Depósito indevido de objetos/substâncias, alternativa expressa ao ato de atirar do veículo.',notes=['Não atribuir automaticamente ao condutor toda conduta de qualquer pessoa sem verificar regime de responsabilidade.'])
add(176,'Condutor envolvido em sinistro com vítima pode providenciar socorro e deixa de fazê-lo. Resposta: analisar inciso I, gravíssima com multa cinco vezes e suspensão.', 'O policial determina remover o veículo: a preservação do local não elimina a hipótese do inciso IV de adotar providências para remoção determinada.', 'O dever de socorro do inciso I ignora a possibilidade real de agir? Não. O texto inclui podendo fazê-lo; não omitir a condição nem ensinar intervenção médica perigosa.', 'Toda remoção de veículo após sinistro com vítima é proibida pelo artigo? Não. O inciso IV prevê providências quando determinadas por policial ou agente; integrar segurança e preservação.', 'Sinistro com vítima','Evento que ativa deveres específicos do envolvido, distintos do regime sem vítima.',notes=['Não confundir infração administrativa, crime do art. 304 e fuga do art. 305; cada qual tem elementos próprios.'])
add(177,'Autoridade solicita auxílio seguro a condutor para socorrer vítima de sinistro e ele deixa de atender. Resposta: o recorte do artigo é grave, com multa.', 'Condutor envolvido no próprio sinistro tem deveres do art. 176; não trocar grave e gravíssima indiscriminadamente.', 'A classe é gravíssima por ter vítima? Não. A omissão de auxílio solicitado descrita neste artigo é GRAVE, distinta da hipótese do art. 176.', 'O art. 177 exige que a pessoa seja sempre o condutor envolvido no sinistro? Não. Descreve o condutor solicitado pela autoridade e seus agentes, com recorte diverso do 176.', 'Socorro solicitado','Auxílio requerido pela autoridade, sem exigir que o solicitado tenha provocado o evento.',exemplo='Autoridade solicita auxílio seguro a condutor para socorrer vítima e ele deixa de atender. Resposta: no recorte do art. 177, infração grave e multa. Variação: condutor envolvido no próprio sinistro tem deveres específicos do art. 176; não trocar as hipóteses.',notes=['Não ensinar transporte improvisado de pessoa ferida como obrigação universal; socorro deve observar possibilidade e segurança.'])
add(178,'Dois veículos colidem sem vítimas e bloqueiam a circulação. Resposta: adotar providências para remover é necessário à segurança e fluidez; a omissão descrita é média.', 'Se há vítima, não transportar automaticamente a regra do 178: integrar preservação e determinações do art. 176.', 'O artigo exige remover indistintamente todo veículo em qualquer sinistro? Não. O recorte é sem vítima e medida necessária à segurança e fluidez.', 'A presença de vítima é requisito do art. 178? Não. O texto diz SEM vítima; trocar a condição muda a hipótese aplicável.', 'Remoção necessária','Providência de segurança/fluidez em sinistro sem vítima, no recorte legal.',notes=['Não confundir obrigação de adotar providências com ignorar impossibilidade material ou criar risco para mover o veículo.'])
add(179,'O motorista faz reparo na pista da rodovia sem impedimento absoluto de remoção. Resposta: a hipótese do inciso I é grave, com multa e remoção.', 'Se há impedimento absoluto de remover E sinalização adequada, a exceção do caput deve ser examinada; sinalizar sozinho não a completa.', 'A exceção se satisfaz apenas por ligar pisca-alerta em todo reparo? Não. Exige impedimento absoluto de remoção e veículo devidamente sinalizado.', 'Reparo em qualquer via tem a mesma classe grave? Não. Pista de rodovia/trânsito rápido: grave com remoção; demais vias: leve, conforme incisos.', 'Reparo excepcional','Intervenção sob impedimento absoluto e sinalização, requisitos cumulativos.',notes=['Não transformar sinalização isolada em permissão geral de manutenção na via pública.'])
add(180,'O veículo fica imobilizado na via porque acabou o combustível. Resposta: é média com multa e remoção no recorte do artigo.', 'Uma pane elétrica sem vínculo com falta de combustível não é automaticamente a descrição completa do 180; outros deveres de segurança permanecem.', 'O art. 180 enquadra qualquer pane como falta de combustível? Não. Exige imobilização na via por essa causa, sem generalizar a toda avaria.', 'A consequência textual é só multa, sem medida administrativa? Não. O artigo também prevê remoção do veículo, distinta de retenção para apresentar habilitado.', 'Pane por combustível','Causa específica da imobilização descrita, distinta de toda pane mecânica.',notes=['Não inventar tolerância universal de distância até posto nem tratar falta de combustível como excludente automática de autuação.'])
add(181,'Veículo estaciona na vaga reservada a idoso sem credencial. Resposta: inciso XX, gravíssima com multa e remoção, distinto do inciso XVII de estacionamento regulamentado.', 'Estacionar na contramão, inciso XV, tem multa média, mas não enumera remoção como todos os outros incisos; não afirmar sempre remoção.', 'Todo inciso de estacionamento prevê obrigatoriamente remoção? Não. O inciso XV não lista essa medida; examinar cada hipótese sem copiar consequência universal.', 'Exatamente um metro do meio-fio é mais de um metro e infração grave do III? Não. A faixa de cinquenta centímetros a UM metro é leve no II; o III exige MAIS DE um metro.', 'Estacionamento por hipótese','Conduta com classe e medida próprias, sem regra universal de gravidade ou remoção.',simples='O art. 181 tem hipóteses específicas de estacionamento. Não há classe ou medida universal: contramão (XV) é média e não enumera remoção; fila dupla é grave; pista de rodovia/estrada/trânsito rápido/via com acostamento é gravíssima. Distância da guia de 50 cm a 1 m é leve; MAIS DE 1 m, grave. Vaga reservada sem credencial é inciso XX, gravíssima, distinto do XVII regulamentado. Acostamento tem ressalva de força maior e ponto de ônibus tem delimitador ou intervalo subsidiário próprio.',pontos=['II: 50 cm a 1 m, LEVE; III: mais de 1 m, GRAVE.','V: pista de estradas, rodovias, trânsito rápido ou via dotada de acostamento, GRAVÍSSIMA.','VII: acostamento, LEVE, salvo força maior.','XI: fila dupla, GRAVE; XV: contramão, MÉDIA, sem remoção enumerada no inciso.','XVII: estacionamento regulamentado, GRAVE; XVIII: proibido estacionar, MÉDIA; XIX: proibido parar/estacionar, GRAVE.','XX: vaga reservada sem credencial, GRAVÍSSIMA.','XIII: delimitador do ponto; sem ele, dez metros ANTES E DEPOIS do marco.','§1º: aplicação preferencialmente após remoção não torna remoção pressuposto universal de toda multa.'],atencao=['Não dizer sempre multa e remoção; conferir inciso específico e regime de aplicação.','Não afirmar acostamento sem a ressalva de força maior.','Requisitos de vagas reservadas e sinalização devem ser integrados ao regime atual; não confundir art. 86-A e inciso XX.'])
add(182,'Veículo faz parada para embarque na esquina a menos de cinco metros. Resposta: média, mesma classe da hipótese correspondente de estacionamento; não há menor gravidade universal.', 'Parar sobre ciclovia é grave no inciso XI; sobre passeio/faixa de pedestre, no inciso VI, leve, sem equiparar todas as posições.', 'Toda parada irregular é sempre menos grave que estacionamento no mesmo ponto? Não. Há hipóteses de mesma classe, como esquina e contramão; comparar inciso por inciso.', 'O art. 182 enumera remoção do veículo como medida padrão? Não. Os incisos listam multa, sem medida de remoção enumerada; outras regras precisam de fundamento próprio.', 'Parada irregular','Enquadramento ligado à imobilização para embarque/desembarque, com hipóteses próprias.',simples='Paradas irregulares têm classes por inciso: leve em posição, distância de 50 cm a 1 m, passeio/faixa de pedestre; média em esquina, distância acima de 1 m, cruzamento prejudicado, pontes/viadutos/túneis, contramão e local proibido; grave na pista das vias especificadas e sobre ciclovia/ciclofaixa. Não dizer sempre menos grave que estacionar: algumas classes coincidem. O artigo não enumera remoção como medida padrão.',atencao=['Comparar cada inciso, sem regra universal de menor gravidade.','Lei 14.071/2020 acrescentou XI: ciclovia/ciclofaixa GRAVE, distinto do VI.'],sources=[L2020])
add(183,'Na mudança do semáforo, o condutor para sobre a faixa de pedestres. Resposta: a hipótese específica é média com multa.', 'Parada fora dessa situação pode exigir outro inciso; não enquadrar qualquer presença na faixa pelo 183 sem examinar mudança de sinal.', 'A mudança de sinal integra a descrição do art. 183? Sim. O texto descreve parar sobre faixa na mudança de sinal luminoso, com classe média.', 'Toda parada sobre faixa tem sempre classe leve do art. 182, VI? Não. Há hipótese específica média no art. 183 vinculada à mudança do sinal.', 'Parada no semáforo','Hipótese específica na mudança de luz, distinta da descrição geral da parada.',notes=['Distinguir arts. 182, VI, 183 e bloqueio de interseção; não criar preferência sobre pedestre pela mudança da luz.'])
add(185,'Um veículo lento de grande porte deixa a faixa direita sem situação regular que justifique. Resposta: examinar inciso II, infração média.', 'A ultrapassagem tem regras próprias; não transformar qualquer uso momentâneo de outra faixa em proibição absoluta sem integrar circulação e sinalização.', 'O inciso I traz exceção para emergência? Sim. A obrigação de conservar faixa regulamentada tem a exceção textual de emergência.', 'Um caminhão nunca pode usar outra faixa em qualquer situação? Não. Integrar regras de manobra/ultrapassagem e sinalização; não tornar o resumo em proibição absoluta.', 'Conservação da faixa','Manutenção na faixa pertinente, integrada às exceções e demais regras de circulação.',notes=['Não estender a exceção textual do inciso I indiscriminadamente a qualquer desvio nem ignorar manobras regulares.'])
add(186,'Veículo entra na contramão de via sinalizada de sentido único. Resposta: gravíssima; em duplo sentido a hipótese ordinária é grave.', 'Em duplo sentido, usar faixa contrária apenas para ultrapassagem permitida, no tempo necessário e respeitada preferência oposta, tem exceção específica.', 'A exceção de ultrapassagem do inciso I libera toda contramão em mão única? Não. Refere-se a via de duplo sentido e exige condições; mão única tem hipótese gravíssima.', 'Basta alegar ultrapassagem para afastar qualquer irregularidade? Não. Devem ser respeitados tempo necessário, preferência contrária e demais proibições de ultrapassagem.', 'Contramão condicionada','Uso excepcional na ultrapassagem regular em via de duplo sentido.',notes=['Não usar a exceção para legalizar ultrapassagem proibida por linha, curva, cruzamento ou outras condições pertinentes.'])
add(187,'Um caminhão entra em local/horário vedado pela regulamentação competente. Resposta: art. 187, I, média; não recuperar inciso II revogado como regra geral de grave para carga.', 'Faixa exclusiva ou passagem por calçada tem tipos específicos; não afirmar que toda proibição de circulação, qualquer que seja, cabe exclusivamente no 187.', 'O inciso II revogado ainda cria classe grave geral para caminhões? Não. O rol atual mantém inciso I para todos os tipos no recorte de locais/horários.', 'Toda restrição de trânsito necessariamente afasta outros artigos específicos? Não. Examinar descrição e sinalização pertinentes, sem absorver toda infração no tipo geral.', 'Restrição de local/horário','Limitação regulamentar do art. 187, distinta de todo tipo de circulação proibida.',atencao=['Inciso II revogado pela Lei 9.602/1998; não ensinar rol histórico como atual.','Não generalizar todas as restrições se enquadram no I quando há tipo específico aplicável.'])
add(188,'Dois veículos circulam lado a lado interrompendo o trânsito. Resposta: a perturbação/obstrução compõe a infração média.', 'A simples circulação paralela regular em faixas distintas não completa automaticamente a hipótese.', 'Circular lado a lado, sem perturbação, basta sempre para o art. 188? Não. O texto exige interromper ou perturbar o trânsito, não proibição de toda circulação paralela.', 'A classe do tipo é gravíssima apenas por haver dois veículos? Não. A descrição do art. 188 é MÉDIA; outras condutas têm requisitos próprios.', 'Circulação perturbadora','Trânsito paralelo com interferência no fluxo, distinto de circular regularmente em faixas.',notes=['Não omitir interrompendo ou perturbando da descrição.'])
add(189,'Uma ambulância em serviço de urgência usa identificação sonora e luminosa regulamentar e o condutor não dá passagem. Resposta: o recorte é gravíssimo.', 'Não confundir mera aparência de ambulância estacionada sem urgência com todos os requisitos desta descrição.', 'A identificação só por nome pintado no veículo completa o art. 189? Não. O texto menciona serviço de urgência e dispositivos regulamentares de alarme sonoro e iluminação intermitente.', 'Recusar passagem e seguir para aproveitar a abertura têm mesma classe? Não. Art. 189 é gravíssima; seguir no art. 190 é grave, com condições próprias.', 'Prioridade identificada','Condição especial de urgência e sinalização para a hipótese administrativa.',notes=['Integrar art. 29 atual sem afirmar que toda prioridade de veículo policial só existe numa única situação.'],sources=[L2022])
add(190,'O motorista segue veículo de urgência para aproveitar a passagem aberta com alarme e iluminação. Resposta: examinar art. 190, grave com multa.', 'A distância frontal de segurança é obrigação distinta; o artigo não autoriza seguir o veículo urgente apenas porque ficou distante.', 'O art. 190 exige um número fixo de metros de proximidade? Não. Não fixa distância numérica; descreve seguir veículo urgente com prioridade identificada.', 'A classe é gravíssima como deixar de dar passagem? Não. O art. 190 é GRAVE, distinto da classe do art. 189.', 'Seguir a urgência','Aproveitamento da prioridade identificada, distinto de negar passagem.',pontos=['GRAVE, multa.','Serviço de urgência e prioridade identificada por alarme sonoro e iluminação intermitente.','Não inventar limite de distância no art. 190.'],notes=['Não restringir a apenas seguir de perto porque o texto não fixa essa condição numérica.'],sources=[L2022])
add(191,'Um motorista força passagem na ultrapassagem entre veículos em sentidos opostos prestes a se cruzar. Resposta: gravíssima com multa dez vezes e suspensão.', 'Na reincidência em até doze meses, dobra-se a multa; o artigo não declara automaticamente dobrar o prazo de suspensão.', 'A primeira ocorrência prevê multa simples sem suspensão? Não. A redação atual prevê multa DEZ vezes e suspensão do direito de dirigir.', 'Dobro na reincidência significa dobrar automaticamente toda consequência? Não. O parágrafo dobra a multa prevista, não fixa dobra automática de suspensão.', 'Passagem forçada','Manobra entre veículos opostos na iminência de cruzamento, com sanção própria.',notes=['Não confundir com qualquer ultrapassagem irregular nem inventar prazo fixo de suspensão neste artigo.'])
add(192,'Em chuva e velocidade elevada, o condutor mantém espaço insuficiente lateral/frontal. Resposta: a distância deve considerar velocidade, clima, via e veículo; a falta é grave.', 'Distância segura não é uma metragem única para toda situação; há tipo específico de distância ao ultrapassar bicicleta no art. 201.', 'O art. 192 protege só distância para o veículo da frente? Não. Inclui lateral e frontal entre veículos e em relação ao bordo da pista.', 'Um valor fixo escolhido pelo aluno substitui avaliação das condições? Não. O artigo exige considerar velocidade, clima, local de circulação e veículo no momento.', 'Distância contextual','Espaço de segurança ajustado às condições, distinto de número universal inventado.',notes=['Não transferir indiscriminadamente o valor do art. 201 para toda distância deste artigo.'])
rows['art-148-a']['atencao'].append('O texto do §5º condiciona levantamento a negativo no Renach; o art. 16 da Resolução 923 compilada também menciona cumprimento da penalidade. Distinguir as formulações e o procedimento aplicável, sem ensinar bloqueio perpétuo automático após cumprimento.')
rows['art-148-a']['pontos'].append('§6º: resultado divulgado ao interessado, com finalidade delimitada; não exposição pública irrestrita do laudo.')
rows['art-148-a']['atencao'].append('Resolução 923 compilada, art. 10-A, §3º: periódico não exigido de C/D/E abaixo de setenta com CNH de validade inferior a três anos. Art. 10-B: validade do exame de noventa dias da coleta é diferente da janela retrospectiva mínima de noventa dias.')
rows['art-165-d']['atencao'].append('Resolução 923 compilada, art. 22, §2º: mudar C/D/E para B/AB ou solicitar cancelamento até o trigésimo dia após vencimento afasta esta penalidade. Não estender a dispensa a mudança tardia sem analisar os requisitos.')
assert len(rows)==50 and set(rows)==set(expected)
for key,row in rows.items():
 assert 'Variação:' in row['exemplo'] and len(row['prova'])==2,key
 assert all('?' in q and len(q.split('?',1)[1].strip())>45 for q in row['prova']),key
 assert row['termos'] and all(t['significado'] for t in row['termos'])
Path(sys.argv[2]).write_text(json.dumps({'course_slug':'transito','units':rows},ensure_ascii=False,indent=2)+'\n')
print('50 explicitly reviewed CTB units')
